#include <windows.h>
#include <stdio.h>
static unsigned queries;
static LRESULT CALLBACK child_proc(HWND w, UINT m, WPARAM a, LPARAM b)
{
    if (m == WM_SETFONT) { DestroyWindow(w); return 0; }
    if (m == WM_GETDLGCODE) { ++queries; return DLGC_DEFPUSHBUTTON; }
    return DefWindowProcW(w, m, a, b);
}
int main(void)
{
    WNDCLASSW wc = {0}; HWND root, child; LRESULT result;
    wc.lpfnWndProc = child_proc; wc.lpszClassName = L"P225ChildRetirement";
    wc.hInstance = GetModuleHandleW(NULL);
    if (!RegisterClassW(&wc)) return 2;
    root = CreateWindowExW(0, L"STATIC", L"P225", 0, 0, 0, 10, 10,
        HWND_MESSAGE, NULL, wc.hInstance, NULL);
    child = CreateWindowExW(0, wc.lpszClassName, L"child", WS_CHILD,
        0, 0, 10, 10, root, NULL, wc.hInstance, NULL);
    if (!root || !child) return 3;
    SendMessageW(child, WM_SETFONT, 0, 0);
    SetLastError(0);
    result = SendMessageW(child, WM_GETDLGCODE, 0, 0);
    printf("root-live=%d child-live=%d query-result=%ld child-query-calls=%u error=%lu\n",
        IsWindow(root), IsWindow(child), (long)result, queries, GetLastError());
    if (!IsWindow(root) || IsWindow(child) || result || queries) return 4;
    DestroyWindow(root); UnregisterClassW(wc.lpszClassName, wc.hInstance);
    return 0;
}
